; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: pcw16 (Amstrad PcW16 (Rosanne app)), starts in normal mode
; ============================================================

			org #4100

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, ntc_pcwstack		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 14: Print "1 started"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 15: Wait
			dw p_wait_c

			; 16: Print "2 Capability LOAD"; FileSystem.Capability("LOAD"); " SAVE"; FileSystem.Capability("SAVE")
			dw kw_printstrvar, str3
			dw kw_printnl

			; 17: Wait
			dw p_wait_c

			; 18: Print "3 Devices: "; FileSystem.Devices()
			dw kw_printstrvar, str4
			dw kw_printnl

			; 19: Wait
			dw p_wait_c

			; 20: Print "4 CurrentDevice: "; FileSystem.CurrentDevice(); "  Volume: "; FileSystem.CurrentVolume()
			dw kw_printstrvar, str5
			dw kw_printnl

			; 21: Wait
			dw p_wait_c

			; 22: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; 23: Print "5 Save STEP.DAT..."
			dw kw_printstrvar, str6
			dw kw_printnl

			; 24: Wait
			dw p_wait_c

			; 25: r = FileSystem.Save("STEP.DAT", VarPtr(a), 20)
			dw kw_ztov, var_r

			; 26: Print "  Save gave"; r
			dw kw_printstrvar, str8
			dw kw_printint, var_r
			dw kw_printnl

			; 27: Wait
			dw p_wait_c

			; 28: Print "6 Load STEP.DAT..."
			dw kw_printstrvar, str9
			dw kw_printnl

			; 29: Wait
			dw p_wait_c

			; 30: r = FileSystem.Load("STEP.DAT", VarPtr(b), 20)
			dw kw_ztov, var_r

			; 31: Print "  Load gave"; r; ", "; b(0); " ... "; b(9)
			dw kw_printstrvar, str10
			dw kw_printint, var_r
			dw kw_printstrvar, str11
			dw kw_printint, arr_b
			dw kw_printstrvar, str12
			dw kw_printint, arr_b+18
			dw kw_printnl

			; 32: Print "7 done"
			dw kw_printstrvar, str13
			dw kw_printnl

			; 33: End
			dw kw_printnl0
			dw kw_printstrvar, str14
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; 36: Print "  (press a key)"
			dw kw_printstrvar, str15
			dw kw_printnl

			; 37: Do While Inkey <> 0 : Loop
do2_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_e
			dw do2_t_go
do2_e:

			; 38: Do : Frame : Loop Until Inkey <> 0
do3_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_t
do3_e:
			dw p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_t_go:			ld sp, do2_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_i:			dw 0
var_r:			dw 0
p_wait_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0

; numbers passed by address (read only)
vp_arr_a:			dw arr_a
vp_arr_b:			dw arr_b

; ============================================================
; Strings
; ============================================================

str0:			db "1 started", 0
str1:			db "LOAD", 0
str2:			db "SAVE", 0
str3:			db "2 Capability LOAD0 SAVE0", 0
str4:			db "3 Devices: 0", 0
str5:			db "4 CurrentDevice: 0  Volume: 0", 0
str6:			db "5 Save STEP.DAT...", 0
str7:			db "STEP.DAT", 0
str8:			db "  Save gave", 0
str9:			db "6 Load STEP.DAT...", 0
str10:			db "  Load gave", 0
str11:			db ", ", 0
str12:			db " ... ", 0
str13:			db "7 done", 0
str14:			db "Press a key to end", 0
str15:			db "  (press a key)", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_ivar @data
ntc_ivar:		dw 0			; inputint / inkey: dest var

;## ntc_d_hostix @data
ntc_hostix:		dw 0			; host platforms: IX kept over a firmware / BDOS call

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ex de, hl
			or a
			sbc hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvl ntc_mul
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop de
			jp ntc_mul

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_cpnevl ntc_cmp
kw_cpnevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_data
; Rosanne OS/BIOS function numbers (ROSAN283.DOC; the subset NTC needs).
; BIOS calls (call 003Bh, A = number):                     ;!!XANNE confirm reg
ROS_KEYSTATE    equ #89     ; bios_keystate: A=keyno in, up/down status out
ROS_GETTIME     equ #B0     ; bios_gettime: B hrs, C min, D sec, E ticks
ROS_SETMEM1     equ #BF     ; map a block into Q1 (#4000)      ;!!XANNE number
ROS_GETMEM1     equ #CB     ; the block now in Q1
ROS_SETMEM2     equ #C2     ; map a block into Q2 (#8000)
ROS_GETMEM2     equ #CE     ; the block now in Q2
ROS_SETMEM3     equ #C5     ; map a block into Q3 (#C000)      ;!!XANNE number
ROS_GETMEM3     equ #D1     ; the block now in Q3              ;!!XANNE number
; OS calls (call 003Bh, A = number; the text/graphics/dialog interface):
ROS_SCR_DIRECT  equ #00     ; os_scr_direct: direct character to the screen ;!!XANNE no+regs
ROS_GET_MOUSE   equ #00     ; os_get_mouse_xy                               ;!!XANNE
ROS_MOUSE_ON    equ #00     ; os_mouse_on                                   ;!!XANNE
ROS_MOUSE_OFF   equ #00     ; os_mouse_off                                  ;!!XANNE
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; row (0 based)
ntc_scols:		db 90			; columns
ntc_osa:		db 0			; ntc_os: A on return
ntc_smode:		db 0			; screen mode
ntc_pcwstack	equ ntc_end + 256	; the program's real stack lives above the program image
								; in Q1/resident RAM; SP is swapped to it only for OS calls

;## ntc_plat_os ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_os - A = Rosanne function number, other regs = its arguments.
; SP is the thread; switch to the real stack, make the one OS entry
; (call 003Bh), switch back. A (also in ntc_osa) and the call's output
; regs come back. IX is kept. This is the CP/M ntc_bdos pattern, retargeted
; from "call 5" to "call 003Bh".                              ;!!XANNE confirm 003Bh + arg regs
; ------------------------------------------------------------
ntc_os:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			; interrupts: Rosanne may expect them on across a call ;!!XANNE
			call #003B
			ld sp, (ntc_ip)
			ld (ntc_osa), a
			ld ix, (ntc_hostix)
			jp (ix)

;## ntc_plat_screen ntc_plat_os ntc_plat_data ntc_data
; ntc_plat_putc - A = character to the screen (os_scr_direct), count the column
ntc_plat_putc:
			ld (ntc_pclink), ix
			; A already = char; os_scr_direct takes the char in ? and fn in A ;!!XANNE arg reg
			ld c, a					; park the char            ;!!XANNE which reg os_scr_direct reads
			ld a, ROS_SCR_DIRECT
			ld ix, ntc_pc_back
			jp ntc_os
ntc_pc_back:
			ld ix, (ntc_pclink)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; wrapped
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - CR LF (two os_scr_direct)   ;!!XANNE does Rosanne want 13,10 or a line call?
ntc_plat_newline:
			ld (ntc_pclink), ix
			ld c, 13
			ld a, ROS_SCR_DIRECT
			ld ix, ntc_nl_lf
			jp ntc_os
ntc_nl_lf:
			ld c, 10
			ld a, ROS_SCR_DIRECT
			ld ix, ntc_nl_done
			jp ntc_os
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld ix, (ntc_pclink)
			jp (ix)
ntc_pclink:		dw 0

;## ntc_plat_key ntc_plat_os ntc_data
; ntc_plat_scankey - A = key or 0.  bios_keystate reports up/down of ONE key, so
; a full scan walks the key numbers until one is down, maps it to ASCII, returns.
; This is a placeholder: a single polled read.             ;!!XANNE keyno range + ASCII map
ntc_plat_scankey:
			ld a, ROS_KEYSTATE
			; in: the key number to test in ? ; out: up/down in ?  ;!!XANNE
			jp ntc_os

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld a, ROS_KEYSTATE
			ld ix, ntc_gk_back
			jp ntc_os
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0

;## ntc_plat_frame
ntc_plat_frame:
			jp (ix)

;## ntc_plat_exit ntc_plat_os ntc_plat_data
; ntc_plat_exit - hand the app back to Rosanne (the app's clean exit)
; ;!!XANNE the correct os_ call / return path for an app ending
ntc_plat_exit:
			ld a, #00				; os_app_exit ? ;!!XANNE
			jp ntc_os

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory Small heap must not use.
; In the 16K-page flavour the resident core is #4000-#BFFF and the window is
; Q3 (#C000); the heap lives below the window. Return the window base.
; ;!!XANNE set to the real top of resident data once the layout is fixed.
ntc_plat_memtop:
			ld hl, #C000
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_a		equ ntc_bss + 0		; 20 bytes
arr_b		equ ntc_bss + 20		; 20 bytes
ntc_bss_size	equ 40
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
